def fmt_ms(x):
    """Format milliseconds as a string like '123ms'.

    Negative values raise ValueError. Non-integer values are rounded to the
    nearest whole millisecond.
    """
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise TypeError("x must be a number, got %s" % type(x).__name__)
    if x < 0:
        raise ValueError("milliseconds cannot be negative: %r" % (x,))
    return "%dms" % round(x)
